mapper.select:
SELECT

FROM
sys_flow_template f
LEFT JOIN sys_alarm_class_template ct on ct.template_id = f.templateId
LEFT JOIN sys_alarm_type a ON a.alarm_type_id = ct.alarm_type_id AND a.delete_flag = '0'
WHERE  f.delete_flag = '1'
AND a.type_value = #{typeValue}
AND f.templateType = #{templateType}
AND ct.tenant_id = #{tenantId}
AND ct.event_level = #{eventLevelCode}

SELECT t.user_id, t.user_name, t.user_account, t.org_id FROM vm_userinfo_t t LEFT JOIN vm_user_role_rel_t ur ON t.user_id = ur.user_id WHERE ur.role_id = '6'
AND t.org_id IN
#{labelIdItem}
ORDER BY CHAR_LENGTH(t.org_id) DESC;

SELECT
t.process_link AS processLink,
t.time_limit AS timeLimit
FROM
sys_alarm_class_time t
LEFT JOIN sys_alarm_type  a on a.alarm_type_id = t.alarm_type_id AND a.delete_flag = '0'
WHERE
a.type_value = #{typeValue}
AND t.tenant_id = #{tenantId}

    AND t.process_link = #{processLink}

